[tikz]
\begin{tikzpicture}[scale=0.85]
\draw[<->] (-0.6,0)--(11.8,0);
\foreach \x in {0,0.8,1.6,2.4,3.2,4.0,4.8,5.6,6.4,7.2,8.0,8.8,9.6,10.4,11.2} {\draw (\x,-0.12)--(\x,0.12);}
\foreach \x/\lbl in {0.8/400,2.4/500,4.0/600,5.6/700,7.2/800,8.8/900,10.4/1000} {\node[below,font=\scriptsize] at (\x,-0.15) {$\lbl$};}
\foreach \x in {0.8,1.6,2.4,3.2,4.0,10.4} {\node[font=\small] at (\x,0.5) {$\times$};}
\node[below,font=\scriptsize] at (5.6,-1.0) {Price in thousands of dollars};
\node[font=\small] at (5.6,1.6) {House prices};
\end{tikzpicture}
[/tikz]
Each cross on the number line shows the price of one house in a street. Which price is the outlier?

[tikz]
\begin{tikzpicture}[scale=0.85]
\draw[<->] (-0.6,0)--(11.4,0);
\foreach \x in {0,0.9,1.8,2.7,3.6,4.5,5.4,6.3,7.2,8.1,9.0,9.9,10.8} {\draw (\x,-0.12)--(\x,0.12);}
\foreach \x/\lbl in {0.9/200,2.7/300,4.5/400,6.3/500,8.1/600,9.9/700} {\node[below,font=\scriptsize] at (\x,-0.15) {$\lbl$};}
\foreach \x in {0.9,1.8,2.7,3.6,8.1,9.0,9.9} {\node[font=\small] at (\x,0.5) {$\times$};}
\node[below,font=\scriptsize] at (5.4,-1.0) {Price in thousands of dollars};
\node[font=\small] at (5.4,1.6) {Unit prices in a block};
\end{tikzpicture}
[/tikz]
Each cross on the number line shows the price of one unit in a block. Between which two prices is there a gap?

[tikz]
\begin{tikzpicture}[scale=0.85]
\draw[<->] (-0.6,0)--(11.6,0);
\foreach \x in {0,0.55,1.1,1.65,2.2,2.75,3.3,3.85,4.4,4.95,5.5,6.05,6.6,7.15,7.7,8.25,8.8,9.35,9.9,10.45,11.0} {\draw (\x,-0.1)--(\x,0.1);}
\foreach \x/\lbl in {0/0,1.1/2,2.2/4,3.3/6,4.4/8,5.5/10,6.6/12,7.7/14,8.8/16,9.9/18,11.0/20} {\node[below,font=\scriptsize] at (\x,-0.13) {$\lbl$};}
\foreach \x in {1.65,2.2,2.75,3.3,3.85,9.9} {\node[font=\small] at (\x,0.5) {$\times$};}
\node[below,font=\scriptsize] at (5.5,-1.0) {Height (m)};
\node[font=\small] at (5.5,1.6) {Heights of six trees};
